mapper.select:
SELECT state_key FROM ifj_cluster_state WHERE state_key LIKE CONCAT(#{prefix}, '%', #{keyword}, '%') AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP(3)) ORDER BY state_key
ASC DESC
LIMIT #{size} OFFSET #{start}

SELECT state_key FROM ifj_cluster_state WHERE LOWER(state_key) LIKE LOWER(CONCAT(#{prefix}, '%', #{keyword}, '%')) AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP(3)) ORDER BY state_key
ASC DESC
LIMIT #{size} OFFSET #{start}

SELECT state_key FROM ifj_cluster_state WHERE LOWER(state_key) LIKE LOWER((#{prefix} || '%' || #{keyword} || '%')) AND (expires_at IS NULL OR expires_at > strftime('%Y-%m-%d %H:%M:%f','now')) ORDER BY state_key
ASC DESC
LIMIT #{size} OFFSET #{start}

SELECT * FROM ( SELECT ijob_page_.*, ROWNUM AS ijob_row_no_ FROM (
SELECT state_key FROM ifj_cluster_state WHERE LOWER(state_key) LIKE LOWER((#{prefix} || '%' || #{keyword} || '%')) AND (expires_at IS NULL OR expires_at > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))) ORDER BY state_key
ASC DESC
) ijob_page_ WHERE ROWNUM <= (#{start} + #{size}) ) WHERE ijob_row_no_ > #{start}

mapper.insert:
DECLARE
    new_state_value CLOB := #{stateValue,jdbcType=CLOB};
    new_expires_at TIMESTAMP(3);
BEGIN
    IF #{timeoutSeconds} < 0 THEN
        new_expires_at := NULL;
    ELSE
        new_expires_at := SYS_EXTRACT_UTC(SYSTIMESTAMP) + NUMTODSINTERVAL(#{timeoutSeconds}, 'SECOND');
    END IF;
    UPDATE ifj_cluster_state
    SET state_value = new_state_value,
        expires_at = new_expires_at,
        update_time = SYS_EXTRACT_UTC(SYSTIMESTAMP)
    WHERE state_key = #{stateKey};
    IF SQL%ROWCOUNT = 0 THEN
        BEGIN
            INSERT INTO ifj_cluster_state (state_key, state_value, expires_at)
            VALUES (#{stateKey}, new_state_value, new_expires_at);
        EXCEPTION
            WHEN DUP_VAL_ON_INDEX THEN
                UPDATE ifj_cluster_state
                SET state_value = new_state_value,
                    expires_at = new_expires_at,
                    update_time = SYS_EXTRACT_UTC(SYSTIMESTAMP)
                WHERE state_key = #{stateKey};
        END;
    END IF;
END;

SET NOCOUNT ON;
UPDATE ifj_cluster_state WITH (UPDLOCK, HOLDLOCK)
SET state_value = #{stateValue},
    expires_at = CASE WHEN #{timeoutSeconds} < 0 THEN NULL
                      ELSE DATEADD(SECOND, #{timeoutSeconds}, SYSUTCDATETIME()) END,
    update_time = SYSUTCDATETIME()
WHERE state_key = #{stateKey};
IF @@ROWCOUNT = 0
BEGIN
    INSERT INTO ifj_cluster_state (state_key, state_value, expires_at)
    VALUES (#{stateKey}, #{stateValue},
            CASE WHEN #{timeoutSeconds} < 0 THEN NULL
                 ELSE DATEADD(SECOND, #{timeoutSeconds}, SYSUTCDATETIME()) END)
END;
SET NOCOUNT OFF;
UPDATE ifj_cluster_state SET state_key = state_key WHERE state_key = #{stateKey}

mapper.delete:
DELETE FROM ifj_cluster_state
WHERE state_key IN (
    SELECT state_key FROM (
        SELECT state_key FROM ifj_cluster_state
        WHERE expires_at IS NOT NULL AND expires_at <= CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
        ORDER BY expires_at, state_key
    ) WHERE ROWNUM <= #{limit}
)
